# Test the slow path with general iterables
def iter_index_new(iterable, value, start=0, stop=None):
    import operator
    from itertools import islice

    try:
        seq_index = iterable.index
    except AttributeError:
        # Slow path for general iterables
        if stop is None:
            it = islice(iterable, start, None)
        else:
            it = islice(iterable, start, stop)

        i = start - 1
        try:
            while True:
                i = i + operator.indexOf(it, value) + 1
                yield i
        except ValueError:
            pass
    else:
        # Fast path for sequences
        i = start - 1
        try:
            while True:
                i = seq_index(value, i + 1, stop)
                yield i
        except ValueError:
            pass

# Test with list (has .index method)
print("List test:", list(iter_index_new('abcabc', 'a', 0, 3)))  # [0]
print("List no stop:", list(iter_index_new('abcabc', 'a')))  # [0, 3]
print("List with range:", list(iter_index_new('abcabc', 'a', 2, 5)))  # [3]

# Test with generator (no .index method)
def gen():
    for c in 'abcabc':
        yield c

print("Gen test:", list(iter_index_new(gen(), 'a', 0, 3)))  # [0]
print("Gen no stop:", list(iter_index_new(gen(), 'a')))  # [0, 3]
print("Gen with range:", list(iter_index_new(gen(), 'a', 2, 5)))  # [3]
